import{_ as t,o as a,c as n,an as s}from"./chunks/framework.CnMjY8PM.js";const m=JSON.parse('{"title":"Optimisations de rendu et rendu progressif","description":"","frontmatter":{},"headers":[],"relativePath":"optimisation.md","filePath":"optimisation.md"}'),i={name:"optimisation.md"};function l(r,e,o,p,u,d){return a(),n("div",null,[...e[0]||(e[0]=[s(`<link rel="stylesheet" href="https://use.typekit.net/fnz7ojs.css"><h1 id="optimisations-de-rendu-et-rendu-progressif" tabindex="-1">Optimisations de rendu et rendu progressif <a class="header-anchor" href="#optimisations-de-rendu-et-rendu-progressif" aria-label="Permalink to “Optimisations de rendu et rendu progressif”">​</a></h1><p>Le calcul d’une image de Mandelbrot peut demander beaucoup plus de travail que le budget d’une seule image à l’écran. Le moteur ne réduit pourtant plus la résolution spatiale du calcul : chaque texel visible est demandé à sa position exacte dès le départ.</p><p>Le caractère progressif est désormais <strong>temporel</strong> :</p><ol><li>tous les texels nouveaux ou invalidés deviennent des requêtes exactes ;</li><li>le GPU effectue un nombre adaptatif de tours de calcul par image ;</li><li>les pixels qui n’ont pas terminé conservent leur état pour l’image suivante ;</li><li>une passe bilinéaire fabrique seulement une présentation provisoire ;</li><li>quand tout est terminé, la couleur réutilise le dernier cache d’affichage typé, cohérent avec ces données exactes.</li></ol><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>réinitialisation / bord de pan / AA</span></span>
<span class="line"><span>                  |</span></span>
<span class="line"><span>                  v</span></span>
<span class="line"><span>       requêtes exactes iter = -1</span></span>
<span class="line"><span>                  |</span></span>
<span class="line"><span>                  v</span></span>
<span class="line"><span>       itération par lots adaptatifs</span></span>
<span class="line"><span>          |                    |</span></span>
<span class="line"><span>          | terminé            | budget épuisé</span></span>
<span class="line"><span>          v                    v</span></span>
<span class="line"><span>     donnée exacte       état de continuation</span></span>
<span class="line"><span>          |                    |</span></span>
<span class="line"><span>          +----------+---------+</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>       resolve bilinéaire temporaire</span></span>
<span class="line"><span>                     |</span></span>
<span class="line"><span>                     v</span></span>
<span class="line"><span>             couleur / affichage</span></span></code></pre></div><h2 id="les-etats-d-un-texel" tabindex="-1">Les états d’un texel <a class="header-anchor" href="#les-etats-d-un-texel" aria-label="Permalink to “Les états d’un texel”">​</a></h2><p>La couche 0 de la texture brute suffit à distinguer les états principaux.</p><table tabindex="0"><thead><tr><th>Valeur</th><th>Sens</th></tr></thead><tbody><tr><td>-1</td><td>requête exacte qui n’a pas encore commencé</td></tr><tr><td>0</td><td>pixel classé à l’intérieur</td></tr><tr><td>&gt; 0, avec valeur de z sous le seuil</td><td>calcul commencé, budget de l’image épuisé</td></tr><tr><td>&gt; 0, avec valeur de z au-dessus du seuil</td><td>pixel échappé et terminé</td></tr></tbody></table><p>Il n’existe plus de valeurs négatives -2, -4, -8, etc. Dans l’état brut, la couche 1 vaut 1 pour une donnée exacte. Dans le cache d’affichage, la finesse du support bilinéaire est un exposant dyadique compact dans les métadonnées ; elle n’occupe plus une couche flottante.</p><h2 id="une-seule-passe-d-iteration" tabindex="-1">Une seule passe d’itération <a class="header-anchor" href="#une-seule-passe-d-iteration" aria-label="Permalink to “Une seule passe d’itération”">​</a></h2><p>Le chemin ordinaire fusionne trois responsabilités dans un compute shader :</p><ul><li>démarrer les requêtes exactes ;</li><li>continuer les pixels dont le budget précédent était épuisé ;</li><li>compter les pixels qui demandent encore du travail après la passe.</li></ul><p>Les pixels terminés ne sont pas réécrits. Le compteur de travail restant est le seul signal de convergence utilisé par la boucle de rendu et par le contrôleur de lots.</p><p>Les treize couches brutes sont conservées. Elles contiennent l’état de reprise, les métriques d’orbite et le payload de dérivées, notamment z″, partagé avec l’AA analytique et avec les évolutions de géométrie envisagées.</p><h2 id="lots-temporels-adaptatifs" tabindex="-1">Lots temporels adaptatifs <a class="header-anchor" href="#lots-temporels-adaptatifs" aria-label="Permalink to “Lots temporels adaptatifs”">​</a></h2><p>Le shader reçoit un budget de tours pour chaque texel actif. Le moteur ajuste ce budget à partir du temps GPU de la passe d’itération :</p><ul><li>si l’itération dépasse son budget, le lot diminue ;</li><li>si elle reste nettement sous le budget, le lot augmente ;</li><li>une réinitialisation, un bord nouvellement exposé ou un reseed AA ramène le contrôleur à son minimum ;</li><li>le minimum est un tour, afin qu’une première vague plein écran reste fractionnable même sur un GPU lent.</li></ul><p>Le budget de l’itération réserve explicitement du temps aux passes fixes (reprojection éventuelle, resolve, couleur et présentation AA).</p><h2 id="reprojection-lors-d-un-pan" tabindex="-1">Reprojection lors d’un pan <a class="header-anchor" href="#reprojection-lors-d-un-pan" aria-label="Permalink to “Reprojection lors d’un pan”">​</a></h2><p>Un déplacement entier en texels réutilise l’état brut existant :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ancienne texture A -- gather décalé --&gt; texture B</span></span>
<span class="line"><span>                                            |</span></span>
<span class="line"><span>                                            +-- devient la texture active</span></span></code></pre></div><p>Les texels dont la source sort de la texture deviennent directement des requêtes exactes. Une réinitialisation complète applique la même règle à tous les texels. Il n’y a plus d’ensemencement grossier ni de seconde phase de raffinement.</p><h2 id="resolve-bilineaire-temporaire" tabindex="-1">Resolve bilinéaire temporaire <a class="header-anchor" href="#resolve-bilineaire-temporaire" aria-label="Permalink to “Resolve bilinéaire temporaire”">​</a></h2><p>Le resolve est une passe de présentation, de la texture brute vers un cache typé de cinq attachements logiques : trois scalaires <code>iter</code>, <code>z.x</code>, <code>z.y</code>, une géométrie <code>gradient.xy, courbure, hauteur</code> et un mot de métadonnées.</p><ul><li>Un pixel terminé passe avec un pas exact égal à 1.</li><li>Une requête ou une continuation incomplète cherche quatre voisins terminés sur une grille dyadique, en commençant au pas 2.</li><li>Si le support fin est insuffisant, la recherche essaie 4, 8, 16, etc.</li><li>Si aucun support fiable n’existe, la sortie porte explicitement « aucune donnée ».</li></ul><p>Les quantités continues sont interpolées dans une représentation adaptée : nu lisse relativement à une itération locale, direction complexe normalisée, géométrie analytique et phase de bande sur le cercle. Le gradient et le Laplacien de la hauteur ont déjà été calculés en f32 au point d’échappement ; le resolve les copie pour un pixel exact et les interpole pour une présentation provisoire. Le groupe intérieur ou extérieur dominant évite de fabriquer une fausse bordure.</p><p>Le détail du contrat et de ses unités est décrit dans <a href="./cache-geometrique.html">Cache géométrique compact</a>.</p><p>Cette approximation ne retourne jamais dans la texture brute. Elle ne marque aucun pixel comme terminé et n’influence pas le compteur. Dès que la donnée exacte existe, son pas 1 gagne naturellement sur tout support temporaire.</p><h2 id="image-live-et-image-figee-pendant-le-zoom" tabindex="-1">Image live et image figée pendant le zoom <a class="header-anchor" href="#image-live-et-image-figee-pendant-le-zoom" aria-label="Permalink to “Image live et image figée pendant le zoom”">​</a></h2><p>Le zoom peut afficher une image figée reprojetée pendant que la texture live se recalcule. La fusion compare les pas dans la même unité d’écran :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pas effectif figé = pas figé x échelle figée / échelle live</span></span></code></pre></div><p>La plus petite valeur positive gagne. Une donnée exacte live remplace donc le provisoire, tandis que l’image figée continue de couvrir les zones encore sans support.</p><h2 id="anti-aliasing" tabindex="-1">Anti-aliasing <a class="header-anchor" href="#anti-aliasing" aria-label="Permalink to “Anti-aliasing”">​</a></h2><p>L’AA est un chemin distinct, activé manuellement ou après convergence.</p><ol><li>Le rendu ordinaire converge d’abord.</li><li>Le moteur choisit un décalage sous-pixel.</li><li>Le reseed sélectif remet la frontière concernée en requêtes exactes.</li><li>Le même chemin d’itération reconverge.</li><li>La couleur est accumulée dans une texture rgba16float.</li></ol><p>Le format 16 bits de cette texture est un choix de stockage, indépendant de l’arithmétique des shaders. Les shaders de couleur utilisent désormais un seul chemin arithmétique f32.</p><p>Lorsque le payload z′/z″ est valide, l’AA peut déplacer analytiquement la valeur échappée pour éviter de recalculer certains échantillons. Ce mécanisme reste local à l’AA : il ne remplit pas les voisins du rendu ordinaire.</p><h2 id="ce-que-mesure-le-panneau-de-performance" tabindex="-1">Ce que mesure le panneau de performance <a class="header-anchor" href="#ce-que-mesure-le-panneau-de-performance" aria-label="Permalink to “Ce que mesure le panneau de performance”">​</a></h2><p>Les mesures séparent les coûts :</p><ul><li><strong>Itération</strong> : calcul fractal, piloté par le lot adaptatif ;</li><li><strong>Reprojection</strong> : uniquement lors d’un pan ou d’une réinitialisation ;</li><li><strong>Resolve</strong> : copie ou interpolation temporaire des valeurs et de la géométrie analytique ;</li><li><strong>Couleur</strong> et <strong>Present</strong> : shading, palette et accumulation AA.</li></ul><p>Le nombre « Pixels restants » agrège les requêtes exactes et les continuations. Il n’existe plus de second compteur « pixels actifs » ni de seuil destiné à geler un raffinement spatial.</p><h2 id="resume" tabindex="-1">Résumé <a class="header-anchor" href="#resume" aria-label="Permalink to “Résumé”">​</a></h2><table tabindex="0"><thead><tr><th>Mécanisme</th><th>Rôle</th></tr></thead><tbody><tr><td>Requête exacte -1</td><td>État unique d’un texel neuf ou invalidé</td></tr><tr><td>État de continuation</td><td>Reprendre un calcul interrompu par le budget temporel</td></tr><tr><td>Lot adaptatif</td><td>Ajuster le coût de l’itération au GPU et au FPS demandé</td></tr><tr><td>Resolve bilinéaire</td><td>Présentation provisoire, sans effet sur le calcul</td></tr><tr><td>Reprojection</td><td>Réutiliser l’état lors d’un pan</td></tr><tr><td>Fusion live/figée</td><td>Maintenir une image stable pendant le zoom</td></tr><tr><td>AA sélectif/analytique</td><td>Améliorer les contours après convergence</td></tr></tbody></table><p>Le modèle ordinaire est donc simple : <strong>une grille exacte, un budget temporel adaptatif et un seul fallback bilinéaire purement visuel</strong>.</p>`,45)])])}const h=t(i,[["render",l]]);export{m as __pageData,h as default};
